<script setup lang="ts">
import {computed,reactive,ref} from 'vue';import UiIcon from '../components/UiIcon.vue';import CheckRow from '../components/CheckRow.vue';import {useApi,useAction,useEvents,usePolling,stamp} from '../composables/api';import {packages,route} from '../composables/state'
const api=useApi(),state=ref<any>({packages:[],recovery:{}}),logService=ref(''),log=ref('Выбери «Журнал» у службы.'),forms=reactive<Record<string,any>>({}),opened=new Set<string>(),list=ref<HTMLElement>(),{busy,message,run}=useAction()
const labels:Record<string,string>={running:'Процесс запущен',stopped:'Остановлена',completed:'Завершена',failed:'Ошибка',waiting:'Ожидание',backoff:'Пауза перед повтором'}
const report=computed(()=>state.value.recovery||{}),bootBadge=computed(()=>state.value.recovery_pending?'Проверка ожидается':report.value.checked?(report.value.ok?'Восстановлено':'Есть замечания'):'Нет отчёта')
async function load(){if(busy.value)return;try{const v=await api('/api/apps');state.value=v;packages.value=v.packages||[];for(const p of v.packages||[])if(!opened.has(p.name))forms[p.name]={description:p.description||'',mode:p.web_mode||'auto',port:p.web?.port||'',path:p.web?.path||'/'};if(v.error)message.value=v.error;if(logService.value&&route.active==='apps')await logs(logService.value)}catch(e){message.value=(e as Error).message}}
async function logs(id:string){logService.value=id;try{log.value=(await api('/api/apps/log?service='+encodeURIComponent(id))).text}catch(e){message.value=(e as Error).message}}
function act(data:any){void run(async()=>{await api('/api/apps/action',data);message.value='Готово'}).then(load)}
function save(name:string){const f=forms[name];act({action:'metadata',package:name,description:f.description,mode:f.mode,port:f.port?Number(f.port):null,path:f.path||'/'})}
function webUrl(web:any){const url=new URL(location.href);url.protocol='http:';url.port=String(web.port);url.pathname=web.path;url.search='';url.hash='';return url.href}
function detail(s:any){return[s.detail,s.pid?'PID '+s.pid:'',s.exit!==null&&s.exit!==undefined?'код выхода '+s.exit:'','перезапуск: '+(s.restart||'never'),s.oneshot?'разовая задача':'',s.runtime?'адаптер экрана':''].filter(Boolean).join(' · ')}
useEvents(()=>{if(route.active==='apps'||route.active==='home')void load()});usePolling(load,5000,()=>['apps','home'].includes(route.active)&&!opened.size&&!list.value?.contains(document.activeElement))
</script>
<template>
<header class="page-head"><div><h1><UiIcon name="box" :size="24"/>Приложения</h1><div class="sub">Запуск служб из пакетов YAM · управление на колонке</div></div><button class="btn" id="apps-refresh" :disabled="busy" @click="act({action:'discover'})"><UiIcon name="refresh"/>Обновить</button></header>
<section class="card"><div class="card-head"><h2><UiIcon name="undo"/>Восстановление после перезагрузки</h2><span class="badge" id="apps-boot-badge">{{bootBadge}}</span></div><p class="hint" id="apps-boot-info">{{report.checked?'Последняя проверка: '+stamp(report.checked):'Проверка начнётся после запуска хоста.'}}{{state.paused?' Службы приостановлены на время изменения пакетов.':''}}</p><div id="apps-boot-checks"><CheckRow v-for="c in report.checks||[]" :key="c.name" :name="c.name" :detail="c.detail" :status="c.ok?'ok':'error'"/></div><button class="btn" id="apps-recheck" :disabled="busy" @click="act({action:'recheck'})"><UiIcon name="shield"/>Проверить сейчас</button><p class="hint">Проверяются панель, запуск YAM CLI и выбранные службы. Наличие процесса не подтверждает полную работоспособность приложения.</p></section>
<p class="hint">Автозапуск выключен, пока ты не включишь его для конкретной службы. До 8 служб одновременно. Приложение должно работать на переднем плане. «Остановить» действует до следующей загрузки; отключение автозапуска не останавливает текущий процесс.</p>
<div id="apps-list" ref="list" class="package-list"><article v-for="p in state.packages" :key="p.name" class="card app-card"><div class="card-head"><h2><UiIcon name="box"/>{{p.name}}</h2><span class="badge">{{p.version}}</span></div><p class="app-description">{{p.description||''}}</p><div class="app-web"><template v-if="p.web"><a v-if="p.web.ready" class="btn" :href="webUrl(p.web)" target="_blank" rel="noopener noreferrer"><UiIcon name="arrow-right"/>Открыть интерфейс ↗</a><button v-else class="btn" disabled><UiIcon name="arrow-right"/>Интерфейс недоступен</button></template><p class="hint">{{p.web_detail||'Веб-интерфейс не обнаружен'}}{{p.web?.source?' · '+p.web.source:''}}</p></div>
<div v-for="s in p.services" :key="s.id" class="card service-card"><div class="card-head"><b>{{s.name}}</b><span class="badge">{{labels[s.status]||s.status}}</span></div><p class="hint">{{detail(s)}}</p><div class="row"><button v-for="a in [['start','play','Запустить'],['stop','stop','Остановить'],['restart','refresh','Перезапустить']]" :key="a[0]" class="btn sm" :data-app-action="a[0]" :data-service="s.id" :disabled="busy||(a[0]==='start'&&s.status==='running')" @click="act({action:a[0],service:s.id})"><UiIcon :name="a[1]"/>{{a[2]}}</button><button class="btn sm" :data-app-log="s.id" @click="logs(s.id)"><UiIcon name="log"/>Журнал</button></div><label class="toggle"><span>Автозапуск после загрузки колонки</span><input type="checkbox" :data-app-auto="s.id" :checked="s.autostart" :disabled="busy" @change="act({action:($event.target as HTMLInputElement).checked?'enable':'disable',service:s.id})"></label></div>
<p v-if="!p.services.length" class="hint">В пакете нет деклараций служб. Запуск вручную возможен через консоль.</p>
<details @toggle="($event.target as HTMLDetailsElement).open?opened.add(p.name):opened.delete(p.name)"><summary>Описание и веб-интерфейс</summary><form v-if="forms[p.name]" :data-app-meta="p.name" @submit.prevent="save(p.name)"><label>Описание<input v-model="forms[p.name].description" class="field" name="description" maxlength="2000"></label><label>Ссылка на панель<select v-model="forms[p.name].mode" class="field" name="mode"><option value="auto">Определять автоматически</option><option value="manual">Указать вручную</option><option value="none">Не показывать</option></select></label><div class="row"><label>Порт HTTP (для ручного режима)<input v-model="forms[p.name].port" class="field" name="port" type="number" min="1024" max="65535" placeholder="Не задан"></label><label>Путь<input v-model="forms[p.name].path" class="field" name="path" placeholder="/"></label><button class="btn" type="submit" :disabled="busy"><UiIcon name="check"/>Сохранить</button></div><p class="hint">Автопоиск проверяет HTTP-панель на портах процесса приложения. Ссылка активна после ответа. Свой порт и путь применяются только в ручном режиме; порты в роутере не открываются.</p></form></details></article>
<section v-if="!state.packages?.length" class="card"><h2><UiIcon name="box"/>Пакетов пока нет</h2><p class="hint">Установи приложение с декларацией службы через YAM v2.</p><a class="btn" href="#yam"><UiIcon name="layers"/>Открыть YAM</a></section></div>
<section class="card"><h2 id="apps-log-title"><UiIcon name="log"/>{{logService?'Журнал: '+logService:'Журнал службы'}}</h2><pre class="out" id="apps-log" aria-live="polite">{{log}}</pre><p class="hint">До 256 КБ в файле и одна предыдущая копия на службу. На экран выводятся последние 32 КБ.</p></section><p id="apps-message" class="hint" role="status">{{message}}</p>
</template>
